#!/usr/bin/env bash
# tools/tangle.awk on small webs (chunk expansion, indentation, appending, #line, errors), and every committed web against the
# source files generated from it: a generated file that was edited by hand, or a web changed without regenerating, fails here.
set -euo pipefail
cd "$(dirname "$0")/.."
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
tangle() { awk -f tools/tangle.awk -v out="$work/out" "$@"; }

cat >"$work/a.md" <<'WEB'
Prose is ignored.

```sh
echo <<not a chunk>>
```

```c <<file: demo/a.c>>=
int main(void) {
    <<body>>
}
```

```c <<body>>=
first();
<<more>>
```

```c <<more>>=
second();
```

```c <<body>>=
third();
```
WEB
tangle "$work/a.md"
expected=$'/* Generated by tools/tangle.awk from '"$work"$'/a.md. Do not edit this file; edit the web. */\n#line 8 "'"$work"$'/a.md"\nint main(void) {\n#line 14 "'"$work"$'/a.md"\n    first();\n#line 19 "'"$work"$'/a.md"\n    second();\n#line 23 "'"$work"$'/a.md"\n    third();\n#line 10 "'"$work"$'/a.md"\n}'
[[ "$(cat "$work/out/demo/a.c")" == "$expected" ]] || { echo "tangle: unexpected output:" >&2; cat "$work/out/demo/a.c" >&2; exit 1; }

# Non-C roots carry no directives and no banner.
printf '```text <<file: demo/b.txt>>=\nhello\n```\n' >"$work/b.md"
tangle "$work/b.md"
[[ "$(cat "$work/out/demo/b.txt")" == "hello" ]]

expect_failure() { # description, expected message, web...
    local description="$1" message="$2"; shift 2
    if tangle "$@" 2>"$work/err"; then echo "tangle: $description was accepted" >&2; exit 1; fi
    grep -q "$message" "$work/err" || { echo "tangle: $description: wrong message:" >&2; cat "$work/err" >&2; exit 1; }
}
printf '```c <<file: demo/c.c>>=\n<<missing>>\n```\n' >"$work/c.md"
expect_failure "an undefined chunk" "never defined" "$work/c.md"
printf '```c <<file: demo/d.c>>=\n<<loop>>\n```\n```c <<loop>>=\n<<loop>>\n```\n' >"$work/d.md"
expect_failure "a chunk that includes itself" "includes itself" "$work/d.md"
printf '```c <<file: demo/e.c>>=\nx\n```\n```c <<orphan>>=\ny\n```\n' >"$work/e.md"
expect_failure "an unused chunk" "never used" "$work/e.md"

# Every committed web against the committed generated files.
rm -rf "$work/out"
tangle web/*.md
status=0
for generated in $(cd "$work/out" && find . -type f | sort); do
    cmp -s "$work/out/$generated" "$generated" || { echo "tangle: $generated is not what its web produces (run make tangle)" >&2; status=1; }
done
exit "$status"
